import { Mayarin } from "@mayarin/sdk";

const mayarin = new Mayarin({ apiKey: process.env.MAYARIN_API_KEY });

// Amounts are minor units as strings. No float ever touches money.
const intent = await mayarin.paymentIntents.create(
  {
    merchant: { id: "M-1", name: "Warung Kopi", city: "Jakarta", country: "ID" },
    amount: { amount: "50000.00", asset: "IDR" },
    payer: { asset: "USDC", chain: "base" },
  },
  { idempotencyKey: "order-4711" },
);

intent.state; // "PRICE_LOCKED"
intent.deposit.address; // per-intent, so the match is never ambiguous
intent.amount.display; // "Rp 50.432,00"

// A webhook is a signal, not truth. It wakes the clearing engine,
// which then asks the adapter for the authoritative status.
export async function POST(request: Request) {
  const event = mayarin.webhooks.verify(await request.text(), request.headers);

  if (event.type === "payment_intent.settled") {
    await fulfil(event.data.reference);
  }

  return new Response(null, { status: 204 });
}

